intro:
Increments the iterator.

Let parent_ be the underlying pointer to enclosing chunk_view.

1) Equivalent to:
++*parent_->current_;
if (*parent_->current_ == ranges::end(parent_->base_))
    parent_->remainder_ = 0;
else
    --parent_->remainder_;
return *this;
Before invocation of this operator the expression *this == std::default_sentinel must be false.

2) Equivalent to ++*this.

recommendedExamples.code:
#include <iostream>
#include <iterator>
#include <ranges>
#include <sstream>

int main() {
    auto letters = std::istringstream{"ABCDEFGHIJK"};

    auto chunks = std::ranges::istream_view<char>(letters) | std::views::chunk(4);

    for (auto chunk : chunks) {
        // chunk is an object of type chunk_view::outer_iterator::value_type
        std::cout << '[';
        for (auto inner_iter = chunk.begin(); inner_iter != std::default_sentinel;
            ++inner_iter)
            std::cout << *inner_iter;
        std::cout << "] ";
    }
    std::cout << '\n';
}
